"use client";

import { clsx } from "clsx";
import { cancelFrame, frame, spring, type FrameData, type KeyframeGenerator } from "motion";
import { useEffect, useId, useImperativeHandle, useRef, type CSSProperties, type Ref } from "react";

export type AsciiTerrainProps = {
  cellSize?: number;
  amplitude?: number;
  speed?: number;
  seed?: number;
  characters?: string;
  paused?: boolean;
  interactive?: boolean;
  ariaLabel?: string;
  /** Sends ripples from code, such as a self-running preview. */
  ref?: Ref<AsciiTerrainHandle>;
  className?: string;
  style?: CSSProperties;
};

export type AsciiTerrainHandle = {
  /** Sends a ripple from a point on the ground: each of x and z runs from -1 to 1, 0 the centre. */
  ripple: (x?: number, z?: number) => void;
};

type Point = { x: number; z: number; screenX: number; screenY: number; baseY: number };
type Ripple = { x: number; z: number; started: number; released?: number };
// A value that follows a target with a Motion spring, advanced on the terrain's own clock
// so pausing, scrolling offscreen, or hiding the tab freezes it exactly where it was.
type Follower = {
  value: number;
  target: number;
  elapsed: number;
  done: boolean;
  generator: KeyframeGenerator<number>;
};
type Controls = {
  sync: () => void;
  move: (x: number, y: number) => void;
  leave: () => void;
  key: (key: string) => void;
  ripple: () => void;
  send: (x: number, z: number) => void;
};

const ramp = ".:-=+*#%@";
const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const finite = (value: number, fallback: number) => (Number.isFinite(value) ? value : fallback);
const smoothstep = (value: number) => {
  const progress = clamp(value, 0, 1);
  return progress * progress * (3 - 2 * progress);
};
// Critically damped with a response of about half a second (2π / √144), so the hill follows
// the pointer closely and settles without overshoot. Stiffness and damping, not a duration,
// because Motion's duration-based springs drop the velocity a retarget hands them.
// 144 and 24 keep the damping ratio at exactly 1.
const hillSpring = { stiffness: 144, damping: 24, mass: 1, restDelta: 0.0001, restSpeed: 0.001 };
// Under reduced motion a ripple is a glow that fades in and back out where it was sent.
const glowRise = 0.12;
const glowFall = 0.6;

function follower(value: number): Follower {
  return {
    value,
    target: value,
    elapsed: 0,
    done: true,
    generator: spring({ ...hillSpring, keyframes: [value, value] }),
  };
}
function advance(follow: Follower, milliseconds: number) {
  if (follow.done) return;
  follow.elapsed += milliseconds;
  const state = follow.generator.next(follow.elapsed);
  follow.value = state.value;
  follow.done = state.done;
}
function springTo(follow: Follower, target: number) {
  if (target === follow.target) return;
  // Retargeting from the current value and velocity keeps every reversal smooth.
  const velocity = follow.done ? 0 : (follow.generator.velocity?.(follow.elapsed) ?? 0);
  follow.generator = spring({ ...hillSpring, keyframes: [follow.value, target], velocity });
  Object.assign(follow, { target, elapsed: 0, done: false });
}
function jump(follow: Follower, value: number) {
  Object.assign(follow, follower(value));
}

export function AsciiTerrain({
  cellSize = 10,
  amplitude = 1,
  speed = 1,
  seed = 7,
  characters = ramp,
  paused = false,
  interactive = true,
  ariaLabel = "ASCII terrain with rolling hills",
  ref,
  className,
  style,
}: AsciiTerrainProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controlsRef = useRef<Controls | null>(null);
  const pausedRef = useRef(paused);
  const pressRef = useRef("");
  const timeRef = useRef(0);
  const driftRef = useRef(0);
  const instructionsId = useId();
  const spacing = clamp(finite(cellSize, 10), 6, 24);
  const height = clamp(finite(amplitude, 1), 0, 2);
  const rate = clamp(finite(speed, 1), 0, 3);
  const phase = finite(seed, 7) % 1000;
  // Printable ASCII keeps every glyph one cell wide and excludes control characters.
  const glyphs = characters.replace(/[^\x21-\x7e]/g, "").slice(0, 32) || ramp;

  useEffect(() => {
    pausedRef.current = paused;
    controlsRef.current?.sync();
  }, [paused]);

  // A ripple sent from code is not input, so it also runs without the controls and inside an
  // inert container, where the landscape itself holds still.
  useImperativeHandle(ref, () => ({ ripple: (x = 0, z = 0) => controlsRef.current?.send(x, z) }), []);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!root || !canvas || !context) return;

    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    let wasStill = motion.matches;
    let visible = false;
    let running = false;
    let width = 0;
    let viewHeight = 0;
    let color = "";
    let fontFamily = "monospace";
    let inert = false;
    let points: Point[] = [];
    let ripples: Ripple[] = [];
    const pointer = { x: follower(0), z: follower(0), strength: follower(0), targetX: 0, targetZ: 0 };
    // Reduced motion keeps every glyph in place and answers input with light instead: an instant
    // highlight where a hill would rise, and a glow that fades where a ripple would spread.
    const still = () => motion.matches;
    const aim = (x: number, z: number) => {
      pointer.targetX = x;
      pointer.targetZ = z;
      if (still()) {
        jump(pointer.x, x);
        jump(pointer.z, z);
      } else {
        springTo(pointer.x, x);
        springTo(pointer.z, z);
      }
    };
    const activate = (active: boolean) => {
      if (still()) jump(pointer.strength, active ? 1 : 0);
      else springTo(pointer.strength, active ? 1 : 0);
    };
    const canMove = () => !pausedRef.current && !root.closest("[inert]");
    const canInteract = () => interactive && canMove();
    // An inert terrain is a still picture, apart from ripples sent to it from code.
    const canAnimate = () =>
      visible &&
      !document.hidden &&
      !pausedRef.current &&
      (!inert || ripples.length > 0) &&
      width > 0 &&
      viewHeight > 0;
    // The landscape only drifts when it has a speed and some height to show it. Otherwise the
    // frame loop runs just while a hill is still settling or a ripple is still fading.
    const drifts = rate > 0 && height > 0;
    const settled = () => pointer.x.done && pointer.z.done && pointer.strength.done;
    const moving = () => ripples.length > 0 || !settled() || (drifts && !still() && !inert);

    function draw() {
      if (!context || !canvas) return;
      context.clearRect(0, 0, width, viewHeight);
      context.font = `${spacing * 0.9}px ${fontFamily}`;
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillStyle = color;
      const time = timeRef.current;
      const reduced = still();
      const drift = driftRef.current;
      const waves = ripples.map((ripple) => {
        const age = time - ripple.started;
        const release = ripple.released === undefined ? 1 : 1 - smoothstep((time - ripple.released) / 0.24);
        const envelope = reduced
          ? smoothstep(age / glowRise) * (1 - smoothstep((age - glowRise) / glowFall)) * 0.5
          : smoothstep(age / 0.24) * Math.exp(-age * 1.2) * 0.3;
        return { x: ripple.x, z: ripple.z, radius: age * 0.85, strength: envelope * release };
      });

      for (const point of points) {
        const { x, z } = point;
        const wave =
          Math.sin(x * 3.3 + z * 1.8 + drift + phase) * 0.26 +
          Math.cos(z * 4.2 - x * 1.3 - drift * 0.7 + phase * 0.7) * 0.2 +
          Math.sin(x * 7.5 + z * 6.2 + drift * 0.5) * 0.07;
        let level = (0.42 + wave) * height;
        const depth = (z + 1) / 2;
        // Pick against the base landscape so a raised hill cannot move its own target.
        point.baseY = viewHeight * (0.28 + depth * 0.56 - level * 0.25);
        const distance = Math.hypot(x - pointer.x.value, z - pointer.z.value);
        const hill = Math.exp(-distance * distance * 10) * pointer.strength.value * 0.65;
        // Under reduced motion hills and ripples brighten glyphs in place instead of moving them.
        let glow = reduced ? hill : 0;
        if (!reduced) level += hill;
        for (const wave of waves) {
          const reach = Math.hypot(x - wave.x, z - wave.z);
          const front = reach - wave.radius;
          if (reduced) glow += Math.exp(-reach * reach * 4) * wave.strength;
          else level += Math.cos(front * 13) * Math.exp(-front * front * 5) * wave.strength;
        }

        point.screenX = width / 2 + x * width * 0.43 * (0.62 + depth * 0.38);
        point.screenY = viewHeight * (0.28 + depth * 0.56 - level * 0.25);
        const shade = clamp((level + glow + 0.12) / 1.15, 0, 1);
        const edge = Math.min(1, (1 - Math.abs(x)) * 8, (1 - Math.abs(z)) * 8);
        context.globalAlpha = (0.24 + shade * 0.7) * (0.45 + depth * 0.55) * edge;
        context.fillText(glyphs[Math.round(shade * (glyphs.length - 1))], point.screenX, point.screenY);
      }
      context.globalAlpha = 1;
      canvas.dataset.ready = "true";
    }

    // Runs in Motion's render step, after any other Motion animations update this frame.
    function tick({ delta }: FrameData) {
      if (!canAnimate()) return stop();
      // Motion clamps long gaps between frames, so a stalled tab cannot fling the terrain forward.
      timeRef.current += delta / 1000;
      // Drift adds up frame by frame, so it holds still under reduced motion while a glow fades.
      if (!still() && !inert) driftRef.current += (delta / 1000) * rate * 0.16;
      // Motion's generators are analytic, so the response is the same at any refresh rate.
      advance(pointer.x, delta);
      advance(pointer.z, delta);
      advance(pointer.strength, delta);
      const life = still() ? glowRise + glowFall : 4;
      ripples = ripples.filter(
        (ripple) =>
          timeRef.current - ripple.started < life &&
          (ripple.released === undefined || timeRef.current - ripple.released < 0.24),
      );
      draw();
      // Everything has come to rest, so the loop rests too until the next input wakes it.
      if (!moving()) stop();
    }

    function stop() {
      if (running) cancelFrame(tick);
      running = false;
    }

    function wake() {
      if (running || !canAnimate() || !moving()) return;
      frame.render(tick, true);
      running = true;
    }

    // Input wakes the loop. A highlight under reduced motion has nothing to animate, so it
    // paints at once instead of waiting for a frame.
    function respond() {
      if (still()) draw();
      wake();
    }

    function sync() {
      stop();
      if (still() !== wasStill) {
        wasStill = still();
        // Hills and ripples do not translate between the moving and the still view, so each
        // starts from the bare landscape.
        jump(pointer.x, pointer.targetX);
        jump(pointer.z, pointer.targetZ);
        jump(pointer.strength, 0);
        ripples = [];
      }
      root!.dataset.motion = motion.matches ? "reduced" : pausedRef.current ? "paused" : "running";
      draw();
      wake();
    }

    function resize() {
      if (!canvas || !root || !context) return;
      width = root.clientWidth;
      viewHeight = root.clientHeight;
      // Bound both the backing store and sample count for large hero sections.
      const ratio = Math.min(window.devicePixelRatio || 1, 2, 2400 / Math.max(width, viewHeight, 1));
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(viewHeight * ratio);
      context.setTransform(ratio, 0, 0, ratio, 0, 0);
      const columns = clamp(Math.floor(width / spacing), 24, 120);
      const rows = clamp(Math.floor(viewHeight / (spacing * 0.75)), 18, 64);
      points = [];
      for (let row = 0; row < rows; row++) {
        for (let column = 0; column < columns; column++) {
          points.push({
            x: (column / (columns - 1)) * 2 - 1,
            z: (row / (rows - 1)) * 2 - 1,
            screenX: 0,
            screenY: 0,
            baseY: 0,
          });
        }
      }
      sync();
    }

    function appearance() {
      const computed = getComputedStyle(root!);
      color = computed.color;
      fontFamily = computed.fontFamily;
      inert = root!.closest("[inert]") !== null;
      sync();
    }

    // An ancestor's class or style changes for many reasons besides a new theme: one that is
    // being animated rewrites its style every frame. Only a change the canvas shows repaints it.
    function themed() {
      const computed = getComputedStyle(root!);
      if (
        computed.color === color &&
        computed.fontFamily === fontFamily &&
        (root!.closest("[inert]") !== null) === inert
      ) {
        return;
      }
      appearance();
    }

    function send(x: number, z: number) {
      const active = ripples.filter((ripple) => ripple.released === undefined);
      if (active.length >= 6) active[0].released = timeRef.current;
      // Fade retiring waves instead of removing a visible wave on the seventh click.
      ripples = [...ripples.slice(-23), { x, z, started: timeRef.current }];
      wake();
    }

    controlsRef.current = {
      sync,
      move(clientX, clientY) {
        if (!canInteract()) return;
        const bounds = root.getBoundingClientRect();
        const x = (clientX - bounds.left) * (width / bounds.width);
        const y = (clientY - bounds.top) * (viewHeight / bounds.height);
        let nearest: Point | undefined;
        let distance = Infinity;
        for (const point of points) {
          const next = (point.screenX - x) ** 2 + (point.baseY - y) ** 2;
          if (next < distance) {
            nearest = point;
            distance = next;
          }
        }
        if (nearest) {
          if (pointer.strength.value < 0.001) {
            // A hill rising from flat ground appears under the pointer instead of sliding in.
            jump(pointer.x, nearest.x);
            jump(pointer.z, nearest.z);
          }
          aim(nearest.x, nearest.z);
          activate(true);
          respond();
        }
      },
      leave() {
        if (!pointer.strength.target) return;
        activate(false);
        respond();
      },
      key(key) {
        if (!canInteract()) return;
        if (key === "Escape") {
          activate(false);
          respond();
          return;
        }
        activate(true);
        let { targetX: x, targetZ: z } = pointer;
        if (key === "Home") x = z = 0;
        if (key === "ArrowLeft") x = clamp(x - 0.12, -0.9, 0.9);
        if (key === "ArrowRight") x = clamp(x + 0.12, -0.9, 0.9);
        if (key === "ArrowUp") z = clamp(z - 0.12, -0.9, 0.9);
        if (key === "ArrowDown") z = clamp(z + 0.12, -0.9, 0.9);
        aim(x, z);
        respond();
      },
      ripple() {
        if (canInteract()) send(pointer.targetX, pointer.targetZ);
      },
      send(x, z) {
        if (!pausedRef.current) send(clamp(finite(x, 0), -1, 1), clamp(finite(z, 0), -1, 1));
      },
    };

    const resizeObserver = new ResizeObserver(resize);
    const intersectionObserver = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      sync();
    });
    const themeObserver = new MutationObserver(themed);
    for (let ancestor: HTMLElement | null = root; ancestor; ancestor = ancestor.parentElement) {
      themeObserver.observe(ancestor, { attributes: true, attributeFilter: ["class", "style", "inert"] });
    }
    appearance();
    resize();
    resizeObserver.observe(root);
    intersectionObserver.observe(root);
    motion.addEventListener("change", sync);
    document.addEventListener("visibilitychange", sync);
    document.fonts?.addEventListener("loadingdone", appearance);
    window.addEventListener("resize", resize);
    return () => {
      stop();
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      themeObserver.disconnect();
      motion.removeEventListener("change", sync);
      document.removeEventListener("visibilitychange", sync);
      document.fonts?.removeEventListener("loadingdone", appearance);
      window.removeEventListener("resize", resize);
      controlsRef.current = null;
      canvas.width = canvas.height = 0;
      delete canvas.dataset.ready;
    };
  }, [spacing, height, rate, phase, glyphs, interactive]);

  return (
    <div
      ref={rootRef}
      data-slot="ascii-terrain"
      role={interactive ? "group" : "img"}
      aria-label={ariaLabel}
      className={clsx("text-foreground relative h-96 w-full overflow-hidden font-mono", className)}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 size-full" />
      {interactive ? (
        <>
          <button
            type="button"
            aria-label="Interact with terrain"
            aria-describedby={instructionsId}
            className="focus-visible:outline-ring absolute inset-0 size-full cursor-crosshair touch-pan-y border-0 bg-transparent p-0 focus-visible:-outline-offset-4"
            onPointerMove={(event) => {
              if (event.isPrimary) controlsRef.current?.move(event.clientX, event.clientY);
            }}
            onPointerLeave={() => controlsRef.current?.leave()}
            onPointerCancel={() => controlsRef.current?.leave()}
            onBlur={() => controlsRef.current?.leave()}
            onPointerDown={(event) => {
              // Mouse and pen ripple on press for instant feedback. Touch waits for the tap, so
              // starting to scroll through the terrain does not send a ripple.
              if (!event.isPrimary || event.button !== 0) return;
              pressRef.current = event.pointerType;
              if (event.pointerType === "touch") return;
              controlsRef.current?.move(event.clientX, event.clientY);
              controlsRef.current?.ripple();
            }}
            onClick={(event) => {
              // A click with no pointer press behind it comes from Enter or Space.
              const pressed = event.detail > 0 ? pressRef.current : "";
              pressRef.current = "";
              if (pressed && pressed !== "touch") return;
              if (pressed) controlsRef.current?.move(event.clientX, event.clientY);
              controlsRef.current?.ripple();
            }}
            onKeyDown={(event) => {
              if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "Escape"].includes(event.key)) {
                event.preventDefault();
                controlsRef.current?.key(event.key);
              }
            }}
          />
          <span id={instructionsId} className="sr-only">
            Move the pointer or use arrow keys to raise hills. Click, press Enter, or press Space to send a
            ripple. Home centers the hill. Escape releases it. Interactions stop while paused. With reduced
            motion, the terrain stays still: it highlights where you point and glows where you click.
          </span>
        </>
      ) : null}
    </div>
  );
}
